export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Makes a project key unique the way `uniqueSlug` makes an address unique:
 * `WV` → `WV2` → `WV3` …, trimming the base so the key never exceeds four
 * characters. Callers pass every key in the workspace, archived ones included.
 */
export function uniqueProjectKey(input: string, taken: Iterable<string>): string {
  const used = new Set(taken);
  if (!used.has(input)) return input;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const digits = String(suffix);
    const candidate = `${input.slice(0, PROJECT_KEY_MAX_LENGTH - digits.length)}${digits}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new Error(`No free project key left for ${input}`);
}

